 if(action==='table-start'){const forms=keepsakes.inhabited;if(forms.length<2)throw Error('Inhabit two different vessels before seating them here.');tableSession=createTableSession({form:forms.includes(run?.form)?run.form:forms[0],seats:forms.slice(-2),boons:availableTableBoons(keepsakes)});tableChoice=null;}
