  const playable=run&&!menu&&run.phase==='playing';$('pause-button').textContent=playable&&paused?'Resume':'Pause';$('pause-button').disabled=!playable||online.role==='guest';$('gear-list').innerHTML=Object.values(run?.loadout??meta.loadout).filter(Boolean).map(id=>`<span class="boon-chip" title="${escapeText(EQUIPMENT[id].desc)}">${EQUIPMENT[id].name}</span>`).join('');$('key-list').innerHTML=Object.entries(KEYS).filter(([,key])=>worldOf(key.room)===worldOf(run?.room??'threshold')).map(([id,key])=>`<span class="key-chip ${(run?.keys??meta.keys??[]).includes(id)?'found':''}" style="--key-color:${key.color}" title="${key.place}">${KEY_ICON} ${(run?.keys??meta.keys??[]).includes(id)?key.name:key.name+' · missing'}</span>`).join('');const resonance=!!run?.abilities.includes('morph');const power=powerProfile(run??{training:meta.training},form),cooldown=view.player?.powerCooldown??0;$('power-button').textContent=hint('power')+' · '+power.name;$('power-button').style.setProperty?.('--ready',Math.max(0,1-cooldown/power.cooldown));$('touch-power').style.setProperty?.('--ready',Math.max(0,1-cooldown/power.cooldown));$('dash-button').textContent=hint('dash')+' · Dash';$('dash-button').style.setProperty?.('--ready',Math.max(0,1-(view.player?.dashCooldown??0)/dashCooldown(run??{boons:{dash:0},training:meta.training},form)));$('dash-button').disabled=!playable||paused;$('touch-dash').style.setProperty?.('--ready',Math.max(0,1-(view.player?.dashCooldown??0)/dashCooldown(run??{boons:{dash:0},training:meta.training},form)));$('power-button').disabled=!playable||paused||remotePaused||onlineWaiting||!view.player||view.player.hp<=0||cooldown>0;$('power-description').textContent=power.desc;$('touch-power').textContent=cooldown>0?cooldown.toFixed(1)+'s':'POWER';$('touch-power').disabled=cooldown>0;const set=matchedSet(run?.loadout??meta.loadout);$('set-bonus').textContent=set?SET_BONUSES[set].name+' · '+SET_BONUSES[set].desc:'Match a weapon and armor for a set bonus.';$('vessel-button').disabled=!(resonance&&playable&&view.player?.hp>0);$('vessel-button').textContent=resonance?hint('morph')+' · Vessels':'Vessels · find resonance';$('touch-morph').hidden=!resonance;$('touch-controls').hidden=!(['descent','dungeon','rematch'].includes(entryMode)&&touchDevice&&run&&run.phase==='playing'&&!paused&&!menu);const compact=['descent','dungeon','rematch'].includes(entryMode)&&playable&&!paused&&!document.querySelector('dialog[open]')&&!railExpanded;$('game-layout').classList.toggle('compact-rail',compact);$('rail-expand').textContent=railExpanded?'Collapse':'Expand';
