  if(online.role==='guest'){const accepting=!paused&&!remotePaused&&!onlineWaiting&&run?.phase==='playing'&&!document.querySelector('dialog[open]');online.input({x:accepting?inputX:0,y:accepting?inputY:0,dash:accepting&&dashRequested,fire:accepting&&(fireHeld||keys.has(settings.bindings.fire)||controller.fire),fireMode:settings.fireMode,power:accepting&&powerRequested,interact:accepting&&(keys.has(settings.bindings.interact)||interactRequested||interactHeld||controller.interact)});dashRequested=false;powerRequested=false;interactRequested=false;}
